const encKSCmsUHCUCS2UD*: string = """
"""

proc rosCids*(ordering: string): string =
  ## Base64 little-endian uint32 array (index CID, 0 unmapped).
  case ordering
  of "Japan1": rosJapan1Cids
  of "GB1": rosGB1Cids
  of "CNS1": rosCNS1Cids
  of "Korea1": rosKorea1Cids
  else: ""

proc rosTop*(ordering: string): int =
  case ordering
  of "Japan1": rosJapan1Top
  of "GB1": rosGB1Top
  of "CNS1": rosCNS1Top
  of "Korea1": rosKorea1Top
  else: 0

proc encRanges*(cmapName: string): seq[CjkMapRange] =
  case cmapName
  of "90ms-RKSJ-H": enc90msRKSJH
  of "90ms-RKSJ-V": enc90msRKSJV
  of "90msp-RKSJ-H": enc90mspRKSJH
  of "90msp-RKSJ-V": enc90mspRKSJV
  of "90pv-RKSJ-H": enc90pvRKSJH
  of "90pv-RKSJ-V": enc90pvRKSJV
  of "GBK-EUC-H": encGBKEUCH
  of "GBpc-EUC-H": encGBpcEUCH
  of "GBpc-EUC-V": encGBpcEUCV
  of "B5-H": encB5H
  of "ETen-B5-H": encETenB5H
  of "KSC-EUC-H": encKSCEUCH
  of "KSCms-UHC-H": encKSCmsUHCH
  else: @[]

proc encCodes*(cmapName: string): seq[CodeRange] =
  case cmapName
  of "90ms-RKSJ-H": enc90msRKSJHCodes
  of "90ms-RKSJ-V": enc90msRKSJVCodes
  of "90msp-RKSJ-H": enc90mspRKSJHCodes
  of "90msp-RKSJ-V": enc90mspRKSJVCodes
  of "90pv-RKSJ-H": enc90pvRKSJHCodes
  of "90pv-RKSJ-V": enc90pvRKSJVCodes
  of "GBK-EUC-H": encGBKEUCHCodes
  of "GBpc-EUC-H": encGBpcEUCHCodes
  of "GBpc-EUC-V": encGBpcEUCVCodes
  of "B5-H": encB5HCodes
  of "ETen-B5-H": encETenB5HCodes
  of "KSC-EUC-H": encKSCEUCHCodes
  of "KSCms-UHC-H": encKSCmsUHCHCodes
  else: @[]

proc encUnicodes*(cmapName: string): string =
  ## Packed code-sorted direct mappings (u16 code, u24 scalar, LE)
  ## from the encoding's UCS2 CMap. Gap-fills CIDs the ROS tables
  ## do not cover.
  case cmapName
  of "90ms-RKSJ-H": enc90msRKSJUCS2UD
  of "90ms-RKSJ-V": enc90msRKSJUCS2UD
  of "90msp-RKSJ-H": enc90msRKSJUCS2UD
  of "90msp-RKSJ-V": enc90msRKSJUCS2UD
  of "90pv-RKSJ-H": enc90pvRKSJUCS2CUD
  of "90pv-RKSJ-V": enc90pvRKSJUCS2CUD
  of "GBK-EUC-H": encGBKEUCUCS2UD
  of "GBpc-EUC-H": encGBpcEUCUCS2CUD
  of "GBpc-EUC-V": encGBpcEUCUCS2CUD
  of "B5-H": encB5pcUCS2CUD
  of "ETen-B5-H": encETenB5UCS2UD
  of "KSC-EUC-H": encKSCpcEUCUCS2CUD
  of "KSCms-UHC-H": encKSCmsUHCUCS2UD
  else: ""

proc hasCjkOrdering*(ordering: string): bool =
  ordering in ["Japan1", "GB1", "CNS1", "Korea1"]

proc hasCjkEncoding*(cmapName: string): bool =
  encRanges(cmapName).len > 0
